	void *response;
	u16 id;
	bool received;
};

int ktcp_begin_transaction(struct ktcp_cb *cb, struct kvm *kvm,
			   struct ktcp_transaction *tx)
{
	int id, ret;

	memset(tx, 0, sizeof(*tx));
	if (mutex_lock_killable(&cb->rlock))
		return ktcp_abort(cb, -EINTR);
	ret = READ_ONCE(cb->error);
	if (ret)
		goto out;
	do {
		id = idr_alloc_cyclic(&cb->transactions, tx, 0, 65536, GFP_KERNEL);
		if (id == 0xff)
			idr_remove(&cb->transactions, id);
	} while (id == 0xff);
	ret = id < 0 ? id : 0;
	if (!ret) {
		tx->kvm = kvm;
		tx->id = id;
	}
out:
	mutex_unlock(&cb->rlock);
	return ret;
}

